import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/db-import-objects.png",n="/relio/shots/en/db-compare-sql.png",f=JSON.parse('{"title":"Import from and apply to a database","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/database.md","filePath":"en/quick/database.md"}'),s={name:"en/quick/database.md"};function l(d,a,p,c,m,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="import-from-and-apply-to-a-database" tabindex="-1">Import from and apply to a database <a class="header-anchor" href="#import-from-and-apply-to-a-database" aria-label="Permalink to &quot;Import from and apply to a database&quot;">​</a></h1><p>Bring the structure of an existing database into a model, and apply a model to a database.</p><h2 id="import-from-a-database" tabindex="-1">Import from a database <a class="header-anchor" href="#import-from-a-database" aria-label="Permalink to &quot;Import from a database&quot;">​</a></h2><ol><li>Open File › Import › From DB.</li><li>Enter the connection details and connect. The drivers for PostgreSQL, MySQL, MariaDB, SQL Server and SQLite are built into the app, so there is nothing else to install.</li><li>Choose the schemas to import.</li><li>Choose the tables, views, sequences and triggers and add them to the document. The whole import is undone with a single <kbd>Ctrl</kbd>+<kbd>Z</kbd>.</li></ol><figure class="shot" data-scene="db-import-objects"><img src="'+i+'" alt="Import from DB — choosing the objects to import" loading="lazy"><figcaption>Import from DB — choosing the objects to import</figcaption></figure><h2 id="apply-to-a-database" tabindex="-1">Apply to a database <a class="header-anchor" href="#apply-to-a-database" aria-label="Permalink to &quot;Apply to a database&quot;">​</a></h2><ul><li><strong>Creating it for the first time</strong> — File › Export to DB… (also on the toolbar). The SQL to run is shown first; on databases that support it, everything runs in one transaction and is rolled back if a statement fails.</li><li><strong>Applying only the changes</strong> — Generate migration SQL (ALTER) from the differences between the model and the database structure. <ol><li>In a new diagram, use Import from DB to bring in the current database structure, and save it as a file (for example <code>db-now.erm</code>).</li><li>Open the model you want to apply and choose that file in File › Compare and merge › Compare with another file….</li><li>In the comparison view, choose Export ▾ › Generate migration SQL (PostgreSQL, MySQL, MariaDB, SQL Server, Oracle).</li><li>Check the warnings about risky changes and the &quot;Manual step required&quot; list, then run the SQL yourself in your database tool. Relio never runs this SQL.</li></ol></li></ul><figure class="shot" data-scene="db-compare-sql"><img src="'+n+'" alt="Migration SQL generated from the comparison view" loading="lazy"><figcaption>Migration SQL generated from the comparison view</figcaption></figure><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Always read the SQL before running it on a real database, and back up production databases first.</p></div><p>For Oracle, prepare the Oracle Instant Client folder first; for Db2, Informix and MS Access, the ODBC driver. H2 and HSQLDB cannot be connected to directly, so export a DDL file and run it. Database passwords are stored in the Windows Credential Manager by default.</p><p><strong>More</strong> → <a href="/relio/en/features/database">Databases</a> · <a href="/relio/en/features/git#generating-migration-sql">Git and merging › Generating migration SQL</a> · <a href="/relio/en/features/troubleshooting#common-problems">Help and troubleshooting</a></p>',11)])])}const g=e(s,[["render",l]]);export{f as __pageData,g as default};
